export type RaiPose = keyof typeof POSES;

/** Rai, the AI assistant mascot. `size` is the width; height follows the artwork. */
export function RaiMascot({
  pose = "still",
  size = 24,
  className,
}: {
  pose?: RaiPose;
  size?: number;
  className?: string;
}) {
  const maskId = useId();
  const { body, face } = POSES[pose];

  return (
    <svg
      viewBox={VIEW_BOX}
      width={size}
      height={size / ASPECT}
      fill="currentColor"
      aria-hidden
      className={className}
    >
      <mask id={maskId}>
        <rect width="100%" height="100%" fill="white" />
        <g transform={`translate(${POSE_OFFSET_X[pose]} 0)`} fill="black">
          {face.map((d) => (
            <path key={d} d={d} />
          ))}
        </g>
      </mask>
      <g mask={`url(#${maskId})`} transform={`translate(${POSE_OFFSET_X[pose]} 0)`}>
        {body.map((d) => (
          <path key={d} d={d} />
        ))}
      </g>
    </svg>
  );
}

// Lottie exports, prepared by scripts/optimize-lottie.mjs. Loaded by URL so
// neither the JSON nor the player lands in the main bundle.
const LOTTIE_URL = { idle: idleUrl, wave: waveUrl, loading: loadingUrl };

export type RaiMotion = keyof typeof LOTTIE_URL;

// Artboard size, plus raiFrame [x, y, w, h]: the region matching the static
// artwork's box.
type LottieFrame = { w: number; h: number; raiFrame: number[] };

const prefersReducedMotion = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches;

type LoadedMotion = {
  lottie: typeof import("lottie-web/build/player/lottie_light").default;
  json: string;
};
const motionCache = new Map<RaiMotion, Promise<LoadedMotion>>();

/**
 * Fetches the player and a motion's JSON, once. Call it ahead of time where a
 * motion is about to play (e.g. before a download starts): fetched on demand,
 * they queue behind whatever the page is busy loading and Rai sits still.
 */
function preloadRaiMotion(motion: RaiMotion): Promise<LoadedMotion> {
  let loading = motionCache.get(motion);
  if (!loading) {
    loading = Promise.all([
      import("lottie-web/build/player/lottie_light"),
      fetch(LOTTIE_URL[motion]).then((response) => {
        if (!response.ok) throw new Error(`Rai ${motion} animation: HTTP ${response.status}`);
        return response.text();
      }),
    ]).then(([{ default: lottie }, json]) => ({ lottie, json }));
    // Let a failed load be retried by the next caller.
    loading.catch(() => motionCache.delete(motion));
    motionCache.set(motion, loading);
  }
  return loading;
}

/**
 * Animated Rai. While `playing`, the Lottie plays (once, or on a loop) and,
 * when done, holds its last frame; otherwise the static still pose shows. The
 * static artwork also covers loading (pulsing, so Rai doesn't look frozen)
 * and reduced motion, so the box never changes size. Motion beyond the box
 * (the wave) spills outside it.
 */
export function RaiAnimated({
  motion,
  playing = true,
  loop = false,
  size = 24,
  className,
}: {
  motion: RaiMotion;
  playing?: boolean;
  loop?: boolean;
  size?: number;
  className?: string;
}) {
  const containerRef = useRef<HTMLSpanElement>(null);
  const animRef = useRef<AnimationItem | null>(null);
  const [reducedMotion] = useState(prefersReducedMotion);
  const [frame, setFrame] = useState<LottieFrame | null>(null);

  useEffect(() => {
    if (!playing || reducedMotion) {
      animRef.current?.pause();
      return;
    }
    if (animRef.current) {
      animRef.current.goToAndPlay(0, true);
      return;
    }
    let cancelled = false;
    preloadRaiMotion(motion).then(
      ({ lottie, json }) => {
        if (cancelled || !containerRef.current) return;
        // Parsed per instance: lottie-web mutates the data it's given.
        const data = JSON.parse(json) as LottieFrame;
        const anim = lottie.loadAnimation({
          container: containerRef.current,
          renderer: "svg",
          loop,
          autoplay: true,
          animationData: data,
        });
        anim.addEventListener("DOMLoaded", () => setFrame(data));
        animRef.current = anim;
      },
      () => {
        // The static artwork stays; nothing else to do.
      },
    );
    return () => {
      cancelled = true;
    };
  }, [playing, reducedMotion, loop, motion]);

  useEffect(() => () => animRef.current?.destroy(), []);

  const showLottie = playing && !reducedMotion && frame !== null;
  let lottieStyle: CSSProperties | undefined;
  if (frame) {
    const [x, y, w] = frame.raiFrame;
    const scale = size / w;
    lottieStyle = {
      left: -x * scale,
      top: -y * scale,
      width: frame.w * scale,
      height: frame.h * scale,
    };
  }

  return (
    <span
      className={`relative inline-block ${className ?? ""}`}
      style={{ width: size, height: size / ASPECT }}
      aria-hidden
    >
      <RaiMascot
        pose={playing && motion === "wave" ? "wave" : "still"}
        size={size}
        className={
          showLottie ? "invisible" : playing && !reducedMotion ? "block animate-pulse" : "block"
        }
      />
      <span
        ref={containerRef}
        className={`rai-lottie pointer-events-none absolute ${showLottie ? "" : "invisible"}`}
        style={lottieStyle}
      />
    </span>
  );
}

/**
 * Toolbar-sized Rai that waves while its button is hovered. Needs a `group`
 * ancestor (ToolbarIconButton provides one). Fits react-icons' IconType so it
 * can be passed wherever an `icon` prop is expected.
 */
export function RaiIcon({ size = 16 }: IconBaseProps) {
  // Lucide glyphs are drawn ~20/24 of their box; the mascot is much wider
  // than tall, so scale up from the icon size to keep its face legible.
  const width = (typeof size === "number" ? size : Number.parseFloat(size)) * 1.5;
  const ref = useRef<HTMLSpanElement>(null);
  const [hovered, setHovered] = useState(false);

  useEffect(() => {
    const group = ref.current?.closest(".group");
    if (!group) return;
    const enter = () => setHovered(true);
    const leave = () => setHovered(false);
    group.addEventListener("pointerenter", enter);
    group.addEventListener("pointerleave", leave);
    return () => {
      group.removeEventListener("pointerenter", enter);
      group.removeEventListener("pointerleave", leave);
    };
  }, []);

  return (
    <span ref={ref} className="contents">
      <RaiAnimated motion="wave" playing={hovered} loop size={width} />
    </span>
  );
}
